Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 1000009;
const int MOD_CONST = 1000000007;

long long fastPower(long long base, long long exponent, long long modulus) {
    long long result = 1;
    long long current = base;
    while (exponent > 0) {
        if (exponent & 1) result = (result * current) % modulus;
        current = (current * current) % modulus;
        exponent >>= 1;
    }
    return result;
}

int visited_positions[MAX_SIZE];

int main() {
#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    int p_value, k_value;
    cin >> p_value >> k_value;
    int total = 1;
    if (k_value == 0) {
        for (int i = 1; i < p_value; ++i)
            total = (long long)total * p_value % MOD_CONST;
        cout << total << endl;
        return 0;
    }
    for (int i = 0; i < p_value; ++i) {
        if (visited_positions[i]) continue;
        int j = i, d = 0;
        do {
            visited_positions[j] = ++d;
            j = (long long)j * k_value % p_value;
        } while (!visited_positions[j]);
        if (fastPower(k_value, d, p_value) == 1)
            total = (long long)total * p_value % MOD_CONST;
    }
    cout << total << endl;
#ifndef ONLINE_JUDGE
    fclose(stdin); fclose(stdout);
#endif
    return 0;
}
